export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function gaussian1D(x,mu=2,sigma=2){if(!(sigma>0))throw Error('sigma must be positive');return Math.exp(-.5*((x-mu)/sigma)**2)}
export function covariance(s1,s2,angle=0){const a=angle*Math.PI/180,c=Math.cos(a),s=Math.sin(a);return [[c*c*s1*s1+s*s*s2*s2,c*s*(s1*s1-s2*s2)],[c*s*(s1*s1-s2*s2),s*s*s1*s1+c*c*s2*s2]]}
export function inverse2(m){const d=m[0][0]*m[1][1]-m[0][1]*m[1][0];if(!(d>0))throw Error('positive determinant required');return [[m[1][1]/d,-m[0][1]/d],[-m[1][0]/d,m[0][0]/d]]}
export function gaussianSteps(x,y,center=[0,0],scales=[2,1],angle=0){if(scales.some(v=>!(v>0)))throw Error('positive scales required');const dx=x-center[0],dy=y-center[1],a=angle*Math.PI/180,c=Math.cos(a),s=Math.sin(a),localX=c*dx+s*dy,localY=-s*dx+c*dy,u=localX/scales[0],v=localY/scales[1],q=u*u+v*v,m=covariance(...scales,angle);return {dx,dy,localX,localY,u,v,q,weight:Math.exp(-q/2),covariance:m,inverse:inverse2(m)}}
export function gaussian2D(x,y,center=[0,0],scales=[2,1],angle=0){const a=angle*Math.PI/180,c=Math.cos(a),s=Math.sin(a),dx=x-center[0],dy=y-center[1];return Math.exp(-.5*(((c*dx+s*dy)/scales[0])**2+((-s*dx+c*dy)/scales[1])**2))}
export function compositeAt(x,y,layers,background=[1,1,1]){let t=1,color=[0,0,0];const trace=layers.map(layer=>{const weight=gaussian2D(x,y,layer.center,layer.scales,layer.angle_deg),alpha=layer.opacity*weight,before=t,contribution=layer.color.map(c=>before*alpha*c);color=color.map((v,i)=>v+contribution[i]);t*=1-alpha;return {name:layer.name,weight,alpha,before,contribution,after:t}});const backgroundContribution=background.map(c=>t*c);return {color:color.map((v,i)=>v+backgroundContribution[i]),transmittance:t,layers:trace,backgroundContribution}}
